    titleTa: "\u0ba4\u0bc7\u0bb0\u0bcd\u0bb5\u0bc1 \u0ba4\u0bbf\u0bb0\u0bc1\u0baa\u0bcd\u0baa\u0bc1\u0ba4\u0bb2\u0bcd \u0b95\u0bc1\u0bb1\u0bbf\u0baa\u0bcd\u0baa\u0bc1\u0b95\u0bb3\u0bcd: \u0ba4\u0bbf\u0b9a\u0bc8\u0baf\u0ba9\u0bcd \u0b87\u0baf\u0bb1\u0bcd\u0b95\u0ba3\u0bbf\u0ba4\u0bae\u0bcd",
